steps.run:
New-Item -ItemType Directory -Force -Path $env:SWCLI_SMOKE_ROOT | Out-Null
$template = & python -I scripts/ci/gate_support/drawing_template.py --program-data $env:ProgramData --installation "C:\Program Files\SOLIDWORKS"
if ($LASTEXITCODE -ne 0) { throw "Drawing template discovery failed" }
python -I scripts/ci/verify-line-font-public.py --output-dir "$env:SWCLI_SMOKE_ROOT\line-font-public" --drawing-template $template
if ($LASTEXITCODE -ne 0) { throw "Public Line Font gate failed; retain report and native trace" }

New-Item -ItemType Directory -Force -Path $env:SWCLI_SMOKE_ROOT | Out-Null
$template = & python -I scripts/ci/gate_support/drawing_template.py --program-data $env:ProgramData --installation "C:\Program Files\SOLIDWORKS"
if ($LASTEXITCODE -ne 0) { throw "Drawing template discovery failed" }
python -I scripts/ci/verify-line-font-calibration.py --output-dir "$env:SWCLI_SMOKE_ROOT\line-font-calibration" --drawing-template $template
if ($LASTEXITCODE -ne 0) { throw "Line font calibration failed; retain original report and trace" }

New-Item -ItemType Directory -Force -Path $env:SWCLI_SMOKE_ROOT | Out-Null
python -I scripts/ci/verify-revolve-public.py --output-dir "$env:SWCLI_SMOKE_ROOT\revolve-public"
if ($LASTEXITCODE -ne 0) { throw "Public revolve acceptance failed; preserve original evidence; no automatic retry" }

New-Item -ItemType Directory -Force -Path $env:SWCLI_SMOKE_ROOT | Out-Null
python -I scripts/ci/verify-step-export-public.py --output-dir "$env:SWCLI_SMOKE_ROOT\step-public"
if ($LASTEXITCODE -ne 0) { throw "Public STEP gate failed; original CLI/daemon evidence is preserved" }
